with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('blive nødt til', 'phrase', 'a8501ff7-9ffb-57f1-ad5f-3b53c24617ae', 1, 'verb', null, 'to have to', 'Jeg bliver nødt til at gå nu.', 'I have to go now.'), ('gå over', 'phrase', '8e36bd6d-9177-527e-9777-b42a8b150af5', 1, 'verb', null, 'to pass (of pain, discomfort)', 'Hovedpinen gik over efter en times søvn.', 'The headache went away after an hour of sleep.'), ('gå over', 'phrase', '41acbae6-5d83-5025-a501-bdcf6cbc5db8', 2, 'verb', null, 'to turn into, to change to', 'Regnen gik over i slud i løbet af natten.', 'The rain turned to sleet during the night.'), ('løbe tør', 'phrase', 'eef777d1-b8bc-52d1-b027-a323978dcc6b', 1, 'verb', null, 'to run out (of supplies)', 'Mælken løb tør i morges.', 'The milk ran out this morning.'), ('komme ud', 'phrase', '8d3df9a3-4aa9-528c-a5a8-89178e795db5', 1, 'verb', null, 'to go out (outside)', 'Jeg kommer ud i haven hver morgen.', 'I go out into the garden every morning.'), ('køre på', 'phrase', 'de2ffd5b-89ed-5f93-bd85-e1a1de76cede', 1, 'verb', null, 'to ride (a vehicle)', 'Han kører på cykel hver dag.', 'He rides his bike every day.'), ('køre til', 'phrase', '1177c608-4ac0-51a3-ac5a-8fc3a6d49d8c', 1, 'verb', null, 'to drive to (a place)', 'Vi kører til stranden hver sommer.', 'We drive to the beach every summer.'), ('trænge til', 'phrase', 'ddebd350-9958-5815-816b-b498bc413107', 1, 'verb', null, 'to need (something)', 'Jeg trænger til en kop kaffe.', 'I need a cup of coffee.'), ('sige ja', 'phrase', 'aeffb308-e3cf-58a6-9992-0bb8a01d534c', 1, 'verb', null, 'to agree', 'Hun sagde ja til invitationen.', 'She accepted the invitation.'), ('stille sig', 'phrase', '89a3aee3-aca9-5b7f-9e33-dfb907137a2e', 1, 'verb', null, 'to pretend (to be something)', 'Han stillede sig uvidende om situationen.', 'He pretended to be unaware of the situation.'), ('skrive med', 'phrase', '5b04d74f-5914-5234-bc1b-921997e0ca97', 1, 'verb', null, 'to correspond', 'Jeg skriver med min ven hver uge.', 'I correspond with my friend every week.'), ('snakke om', 'phrase', '3a7cbefa-2ea2-5a6f-b15d-907a5b6b559a', 1, 'verb', null, 'to talk about', 'De snakker om vejret hver dag.', 'They talk about the weather every day.'), ('gå op', 'phrase', '418dd95b-d9f3-52b7-bb48-40a2d2b2ec4d', 1, 'verb', null, 'to go up', 'Vi gik op ad trappen til anden sal.', 'We walked up the stairs to the second floor.'), ('høre om', 'phrase', '3f7c21eb-e7b0-5cc3-a2f0-c9116c0393bf', 1, 'verb', null, 'to hear about (something)', 'Jeg hørte om ulykken i radioen.', 'I heard about the accident on the radio.'), ('regne med at', 'phrase', '3dd84e8f-1d2a-59e7-93c1-0e71765a3d6f', 1, 'verb', null, 'to expect that', 'Jeg regner med at komme til festen i morgen.', 'I expect to come to the party tomorrow.'), ('ligge med', 'phrase', '25caa864-3af4-5b92-a759-25c51220422b', 1, 'verb', null, 'to sleep with someone', 'Hun har ligget med ham i flere måneder.', 'She has slept with him for several months.'), ('falde af', 'phrase', 'b4a3a59c-7c4b-5295-8fea-85a47db22e07', 1, 'verb', null, 'to fall off', 'Knappen faldt af min jakke i går.', 'The button fell off my jacket yesterday.'), ('løbe efter', 'phrase', 'a54cf3cb-deb7-55ac-96d4-8215cc9f627a', 1, 'verb', null, 'to run after (chase)', 'Hunden løb efter katten i haven.', 'The dog ran after the cat in the garden.'), ('løbe efter', 'phrase', '57ceb591-1588-5fde-becf-0cae617dc827', 2, 'verb', null, 'to run for (fetch)', 'Jeg løber efter en ekstra stol til gæsten.', 'I''ll run and get an extra chair for the guest.'), ('gemme sig bag', 'phrase', '0a0bd4c9-7f62-5de2-8375-b68991bda7fc', 1, 'verb', null, 'to hide behind', 'Børnene gemmer sig bag sofaen, når de leger.', 'The children hide behind the sofa when they play.'), ('tale for', 'phrase', 'e6aa4c13-e012-5e07-9572-a5410d3ba3b2', 1, 'verb', null, 'to speak in favour (of)', 'Hun taler for mere motion i hverdagen.', 'She advocates more exercise in everyday life.'), ('være stille', 'phrase', 'c3676774-767e-5868-a36d-65b0326afed5', 1, 'verb', null, 'to be quiet', 'Børnene er stille i klassen.', 'The children are quiet in class.'), ('tage hjem', 'phrase', '038cc85d-482b-5355-bc0f-4707978f3f31', 1, 'verb', null, 'to go home', 'Jeg tager hjem efter arbejde.', 'I go home after work.'), ('stoppe med', 'phrase', '9a389b69-609f-52f7-8d07-5080ff8f46ab', 1, 'verb', null, 'to quit (an activity)', 'Han stoppede med at ryge sidste år.', 'He quit smoking last year.'), ('ville sige', 'phrase', '430397ad-218a-5c75-9031-b1f6bd37b335', 1, 'verb', null, 'to mean', 'Det vil sige, at vi skal mødes klokken otte.', 'This means that we must meet at eight o''clock.'), ('leve i', 'phrase', '2893159c-1e36-52ab-a2e1-195ef2194de0', 1, 'verb', null, 'to live in (a place, state)', 'De lever i en lille lejlighed.', 'They live in a small apartment.'), ('deltage i', 'phrase', '5967d476-a62e-5d2a-9e94-8391466afba7', 1, 'verb', null, 'to take part in', 'Mange børn deltager i sport efter skole.', 'Many children participate in sports after school.'), ('bryde ud', 'phrase', '8eb32750-e1cf-50ee-947a-87b685443212', 1, 'verb', null, 'to burst out (laughing, crying, applauding)', 'Publikum brød ud i vild jubel.', 'The audience burst into wild cheering.'), ('bryde ud', 'phrase', 'dbae0736-63fa-5cf2-a9b9-67b0b0ce5e1e', 2, 'verb', null, 'to break out (of war, fire, epidemic)', 'En voldsom brand brød ud i bygningen.', 'A violent fire broke out in the building.'), ('træde på', 'phrase', '216feaa2-949f-5931-81df-18a70975d2f6', 1, 'verb', null, 'to step on', 'Han trådte på min fod i bussen.', 'He stepped on my foot in the bus.'), ('være ligeglad', 'phrase', '1951316e-fe68-544f-a816-d7d0d4c31d9e', 1, 'verb', null, 'to not care', 'Jeg er ligeglad med vejret i morgen.', 'I don''t care what the weather is like tomorrow.'), ('tage ud', 'phrase', '63b6553c-fde3-55b5-9f70-a1ec2bdf8242', 1, 'verb', null, 'to go out (to the countryside)', 'Vi tager ud til stranden i morgen.', 'We''re going out to the beach tomorrow.'), ('være i live', 'phrase', '0d46ded9-749b-57d1-b1f7-6c058dc568cf', 1, 'verb', null, 'to be alive', 'Min bedstemor er i live og bor alene.', 'My grandmother is alive and lives alone.'), ('i morgen aften', 'phrase', '35b97b83-96df-5e59-870b-38e3bda0b157', 1, 'adverb', null, 'tomorrow evening', 'Vi skal i biografen i morgen aften.', 'We''re going to the cinema tomorrow evening.'), ('træde ind i', 'phrase', '04cc6776-fefe-58e6-aca4-3042cba3ec48', 1, 'verb', null, 'to join (an organisation, a position)', 'Han trådte ind i hæren sidste år.', 'He joined the army last year.'), ('kæmpe for', 'phrase', '8f655e73-707e-5e41-aa2c-e7ff90f0112b', 1, 'verb', null, 'to fight for', 'De kæmper for bedre vilkår på arbejdspladsen.', 'They are fighting for better conditions in the workplace.'), ('komme til skade', 'phrase', '670c2b2b-78c3-5ca8-8747-f1066d6e1c70', 1, 'verb', null, 'to get injured', 'Han kom til skade under fodboldkampen.', 'He was injured during the football match.'), ('bekymre sig om', 'phrase', '332b171f-a95f-562a-b8fa-8e04c5ad77a6', 1, 'verb', null, 'to worry about', 'Hun bekymrer sig om sin søns helbred.', 'She worries about her son''s health.'), ('tænde for', 'phrase', '9dd421c5-8fd8-5343-8d12-f4e6e28f9103', 1, 'verb', null, 'to turn on', 'Hun tænder for lyset i stuen.', 'She turns on the lights in the living room.'), ('være vant til at', 'phrase', '791bd4ea-563b-5333-bb52-7c041f66debc', 1, 'verb', null, 'to be used to (doing something)', 'Jeg er vant til at stå tidligt op.', 'I''m used to getting up early.'), ('sige farvel', 'phrase', '2ba23467-7681-5c50-8b69-e4b5ae15e603', 1, 'verb', null, 'to say goodbye', 'Hun sagde farvel til sin veninde ved toget.', 'She said goodbye to her friend at the train.'), ('more sig', 'phrase', '69bf105d-0a9f-55d5-926a-cdef2015755b', 1, 'verb', null, 'to enjoy oneself, to have fun', 'Børnene morer sig i haven hele dagen.', 'The children have fun in the garden all day.'), ('tage af sted', 'phrase', '2f00ac56-f26a-5c0d-a4d1-9c165032abee', 1, 'verb', null, 'to set off', 'Vi tager af sted tidligt om morgenen.', 'We leave early in the morning.'), ('sætte sig på', 'phrase', '5ec9da46-35c6-5883-bf81-5f17bc068750', 1, 'verb', null, 'to sit down (on something)', 'Hun sætter sig på stolen hver morgen.', 'She sits down on the chair every morning.'), ('sætte sig på', 'phrase', 'ab68f4ac-faae-500a-911f-5ce81f22d20e', 2, 'verb', null, 'to take control of', 'De satte sig på hele markedet sidste år.', 'They took over the entire market last year.'), ('lade som om', 'phrase', 'eb2879bb-510d-5405-bfdb-230d8d330918', 1, 'verb', null, 'to pretend', 'Hun lader som om hun sover.', 'She pretends to be asleep.'), ('være vild med', 'phrase', '40658091-35c1-5174-8ef8-4532a80f2cad', 1, 'verb', null, 'to be crazy about (something)', 'Jeg er vild med den nye restaurant på hjørnet.', 'I love the new restaurant on the corner.'), ('tvinge sig til at', 'phrase', '8e5067da-a6c6-5e95-90d6-68b0c89ceaba', 1, 'verb', null, 'to force oneself (to do something)', 'Jeg tvang mig til at smile, selvom jeg var ked af det.', 'I forced myself to smile, even though I was sad.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0002' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
